import os,subprocess,json,hashlib,time,resource
from pathlib import Path
lab=Path(__file__).resolve().parent;corpus=lab/'corpus'
env={k:v for k,v in os.environ.items() if not k.startswith('VIBE_')}
env.update(VIBE_LIB=str(corpus/'lib'),VIBE_PREOPEN_DIR=str(corpus),VIBE_RC='1',VIBE_FS_COMPILE='1',VIBE_IMPORT_ABI='raw',VIBE_CHECKED_MODULE_CACHE='off',VIBE_CODEGEN_BODY_CACHE='off',VIBE_DISABLE_PERSISTENT_ARTIFACT_CACHE='1',VIBE_NATIVE_CACHE_DIR=str(lab/'native-cache'))
rows=[];receipts={key:{n:hashlib.sha256((lab/key/n).read_bytes()).hexdigest() for n in ['compiler.wasm','viberun']} for key in ['a','b']}
def corpus_hash():
 h=hashlib.sha256()
 for p in sorted((corpus/'lib').rglob('*')):
  if p.is_file():h.update(str(p.relative_to(corpus)).encode()+b'\0'+p.read_bytes())
 return h.hexdigest()
receipts['corpus_sha256']=corpus_hash()
# Prime native machine-code caches independently of the fresh guest caches.
for key in ['a','b']:
 subprocess.run([str(lab/key/'viberun'),str(lab/key/'compiler.wasm')],cwd=corpus,env=env,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,timeout=120)
for subject,source,entry in [('compiler','lib/@vibe/compiler/tests/codegen_lexer_test.vibe','__no_entry__'),('cli','lib/@vibe/cli/entry.vibe','cli_main')]:
 for rnd in range(4):
  for key in (['a','b'] if rnd%2==0 else ['b','a']):
   private=lab/f'measure-{subject}-{rnd}-{key}';private.mkdir()
   current=env|dict(VIBE_BUILD_CACHE_DIR=str(private/'cache'))
   for temperature in ['cold','warm']:
    dest=private/f'{temperature}.wasm'
    started=time.monotonic();u0=resource.getrusage(resource.RUSAGE_CHILDREN)
    with (private/f'{temperature}.log').open('w') as log:
     p=subprocess.Popen([str(lab/key/'viberun'),str(lab/key/'compiler.wasm'),source,str(dest),entry],cwd=corpus,env=current,stdout=log,stderr=log)
     peak=0
     while p.poll() is None:
      try:peak=max(peak,int(Path(f'/proc/{p.pid}/statm').read_text().split()[1])*os.sysconf('SC_PAGE_SIZE'))
      except FileNotFoundError:pass
      time.sleep(.02)
      assert time.monotonic()-started<300
    wall=time.monotonic()-started;u1=resource.getrusage(resource.RUSAGE_CHILDREN)
    assert p.returncode==0,(subject,key,rnd,temperature)
    rows.append(dict(subject=subject,variant=key,round=rnd,temperature=temperature,wall_s=wall,user_cpu_s=u1.ru_utime-u0.ru_utime,system_cpu_s=u1.ru_stime-u0.ru_stime,peak_rss_bytes=peak,wasm_sha256=hashlib.sha256(dest.read_bytes()).hexdigest()))
    (lab/'measurement.json').write_text(json.dumps(dict(receipts=receipts,protocol='N4 ABBA pairs, identical frozen corpus; isolated parsed-source cache per pair; checked/body/artifact caches off; native JIT primed; RC1 whole FS compile; RSS20ms; no concurrent work.',samples=rows),indent=2)+'\n')
    print(subject,key,rnd,temperature,f'{wall:.4f}s',f'{peak/2**20:.1f}MiB',flush=True)
   assert all(len({r['wasm_sha256'] for r in rows if r['subject']==subject and r['variant']==v})<=1 for v in ['a','b'])
assert corpus_hash()==receipts['corpus_sha256']
print('All32 results stable within each variant; corpus unchanged. Compare sections separately.',flush=True)

