import json,hashlib,statistics
from pathlib import Path
lab=Path(__file__).resolve().parent
measurement=json.loads((lab/'measurement.json').read_text())
def sha(b):return hashlib.sha256(b).hexdigest()
def leb(b,p):
 v=s=0
 while True:
  n=b[p];p+=1;v|=(n&127)<<s
  if n<128:return v,p
  s+=7

def sections(b):
 p=8;out=[]
 while p<len(b):
  start=p;tag=b[p];p+=1;size,p=leb(b,p);end=p+size
  name=''
  if tag==0:
   n,q=leb(b,p);name=b[q:q+n].decode()
  out.append((tag,name,b[start:end]));p=end
 assert p==len(b)
 return out
results={}
for subject in ['compiler','cli']:
 a=(lab/f'measure-{subject}-0-a/cold.wasm').read_bytes();b=(lab/f'measure-{subject}-0-b/cold.wasm').read_bytes()
 sa,sb=sections(a),sections(b)
 assert [(x[0],x[1]) for x in sa]==[(x[0],x[1]) for x in sb]
 changed=[dict(id=x[0],name=x[1],before_bytes=len(x[2]),after_bytes=len(y[2])) for x,y in zip(sa,sb) if x[2]!=y[2]]
 assert all(x['id']==0 and x['name']=='vibe.linemap' for x in changed),changed
 results[subject]=dict(byte_identical=a==b,changed_sections=changed)
summary={}
for subject in ['compiler','cli']:
 for temp in ['cold','warm']:
  variants={}
  for key in ['a','b']:
   samples=[r for r in measurement['samples'] if r['subject']==subject and r['temperature']==temp and r['variant']==key]
   variants[key]=dict(wall_median_s=statistics.median(r['wall_s'] for r in samples),wall_range_s=[min(r['wall_s'] for r in samples),max(r['wall_s'] for r in samples)],peak_rss_median_mib=statistics.median(r['peak_rss_bytes']/2**20 for r in samples))
  variants['wall_change_percent']=(variants['b']['wall_median_s']/variants['a']['wall_median_s']-1)*100
  variants['rss_change_mib']=variants['b']['peak_rss_median_mib']-variants['a']['peak_rss_median_mib']
  summary[f'{subject}_{temp}']=variants
(lab/'summary.json').write_text(json.dumps(dict(summary=summary,output_comparison=results),indent=2)+'\n')
print(json.dumps(dict(summary=summary,output_comparison=results),indent=2))

