import json,collections
from pathlib import Path
lab=Path(__file__).resolve().parent;result={}
for key in ['a','b']:
 result[key]={}
 for subject in ['compiler','cli']:
  counts=collections.Counter();self_counts=collections.Counter();total=0
  for p in sorted((lab/f'profile-{key}-{subject}').glob('[123].json')):
   t=json.loads(p.read_text())['threads'][0];st=t['stackTable'];ft=t['frameTable'];f=t['funcTable'];names=t['stringArray']
   for stack in t['samples']['stack']:
    if stack is None:continue
    total+=1;seen=set();self_counts[names[f['name'][ft['func'][st['frame'][stack]]]]]+=1
    while stack is not None:
     seen.add(names[f['name'][ft['func'][st['frame'][stack]]]])
     stack=st['prefix'][stack]
    counts.update(seen)
  targets=['lc_function_linemap_begin','linemap_flush_fn_into','lc_commit_function_cov','evidence_dict_pass_with_roots','LinkedFunctionPlan::emit']
  result[key][subject]=dict(total_samples=total,inclusive={name:dict(samples=sum(v for n,v in counts.items() if n==name or n.startswith(name+'_exp_')),percent=100*sum(v for n,v in counts.items() if n==name or n.startswith(name+'_exp_'))/total) for name in targets},top_self=[dict(name=n,samples=v,percent=100*v/total) for n,v in self_counts.most_common(25)])
(lab/'cpu-summary.json').write_text(json.dumps(result,indent=2)+'\n')
for key,subjects in result.items():
 for subject,d in subjects.items():print(key,subject,{n:round(v['percent'],2) for n,v in d['inclusive'].items()})
